from pathlib import Path

import pytest

NOTES_DIR: Path = Path("notes")


def _resolve_inside(path: str) -> Path | None:
    """Return the resolved file path under NOTES_DIR, or None if it would leave NOTES_DIR."""
    try:
        base = NOTES_DIR.resolve()
        candidate = (base / path).resolve()
    except (OSError, RuntimeError, ValueError):
        return None
    if not candidate.is_relative_to(base):
        return None
    return candidate


def read_public(path: str) -> str:
    """Return the text of the file at `path` inside NOTES_DIR.

    Returns "" when the file is missing, unreadable, or the path resolves
    outside NOTES_DIR (via "..", an absolute path, or a symlink).
    """
    target = _resolve_inside(path)
    if target is None:
        return ""
    try:
        return target.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


@pytest.fixture
def layout(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    """Chdir into tmp_path with notes/a.txt, notes/sub/, and a secret outside notes."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "notes" / "sub").mkdir(parents=True)
    (tmp_path / "notes" / "a.txt").write_text("alpha", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP SECRET", encoding="utf-8")
    return tmp_path


def test_reads_file_inside_notes(layout: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_nested_path_that_returns_inside_notes(layout: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"


def test_missing_file_gives_empty_string(layout: Path) -> None:
    assert read_public("missing.txt") == ""


def test_directory_gives_empty_string(layout: Path) -> None:
    assert read_public("sub") == ""


def test_parent_traversal_is_blocked(layout: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""


def test_deep_traversal_is_blocked(layout: Path) -> None:
    assert read_public("sub/../../secret.txt") == ""


def test_absolute_path_is_blocked(layout: Path) -> None:
    assert read_public(str(layout / "secret.txt")) == ""


def test_symlink_pointing_outside_is_blocked(layout: Path) -> None:
    (layout / "notes" / "link.txt").symlink_to(layout / "secret.txt")
    assert read_public("link.txt") == ""


def test_null_byte_in_name_is_blocked(layout: Path) -> None:
    assert read_public("a.txt\x00") == ""
